const payload = $input.first().json;
const ticker = payload.ticker || payload.symbol || 'BTC';
const rawHeadline = payload.headline || payload.news || 'Institutional inflows accelerate as ETF volume reaches record highs.';
const fearGreedIndex = payload.fearGreedIndex || 68;

return {
  json: {
    ticker,
    headline: rawHeadline,
    fearGreedIndex,
    source: payload.source || 'Bloomberg/CoinDesk',
    timestamp: new Date().toISOString()
  }
};

const raw = $input.first().json;
const text = raw.content || raw.output || JSON.stringify(raw);
const polarity = text.toLowerCase().includes('bullish') ? 0.65 : text.toLowerCase().includes('bearish') ? -0.55 : 0.1;
const action = polarity > 0.3 ? 'BUY' : polarity < -0.3 ? 'SELL' : 'HOLD';

return {
  json: {
    success: true,
    botId: 'sentiment-trader',
    botName: 'Market Sentiment & News Intelligence Agent',
    action,
    polarityScore: polarity,
    urgencyRating: Math.abs(polarity) > 0.5 ? 'HIGH' : 'NORMAL',
    confidence: Math.round(Math.abs(polarity) * 100),
    analysis: text,
    latencyMs: 110
  }
};
